mapper.select:
select
f.file_relation_id as fileRelationId,
mn.*
from Me_Detection_Guide mn
left join Sys_File f on f.FileID=mn.Dg_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.Dg_Type = #{params.dgType}


    and mn.Dg_Product_Category = #{params.dgProductCategory}


    and mn.Dg_Product like concat('%',#{params.dgProduct},'%')


    and mn.Dg_Item like concat('%',#{params.dgItem},'%')


    and mn.Have_Report = #{params.haveReport}


    order by mn.${params.sortFiled} ${params.sortType}

limit #{params.start},#{params.size}

select
count(1)
from Me_Detection_Guide mn
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.Dg_Type = #{params.dgType}


    and mn.Dg_Product_Category = #{params.dgProductCategory}


    and mn.Dg_Product like concat('%',#{params.dgProduct},'%')


    and mn.Dg_Item like concat('%',#{params.dgItem},'%')
